/* v1.5.6 mobile nav hard-fix + bookings polish */
.bottom-nav{left:0!important;right:0!important;width:100%!important;overflow:hidden!important}
.bottom-inner.guest-nav{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;grid-template-rows:1fr!important;grid-auto-flow:column!important;gap:0!important;width:100%!important;max-width:760px!important;margin:0 auto!important;align-items:end!important;flex-wrap:nowrap!important}
.bottom-inner.admin-nav{display:grid!important;grid-template-columns:repeat(5,minmax(0,1fr))!important;grid-template-rows:1fr!important;gap:0!important;width:100%!important;max-width:760px!important;margin:0 auto!important;align-items:end!important;flex-wrap:nowrap!important}
.bottom-inner .nav-item{min-width:0!important;width:auto!important;max-width:none!important;margin:0!important;padding:8px 2px 10px!important;display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:flex-end!important;gap:4px!important;white-space:nowrap!important}
.bottom-inner .nav-item>span:last-child{font-size:10px!important;line-height:1!important;overflow:hidden!important;text-overflow:ellipsis!important;max-width:100%!important}
.bottom-inner .queue-center{transform:none!important}
.bottom-inner .queue-center .queue-ico{margin-top:-22px!important}
@media(max-width:360px){.bottom-inner .nav-item>span:last-child{font-size:9px!important}}
.booking-group-v2,.booking-date-accordion-v155,.booking-date-card,.booked-slot-card{box-shadow:none!important}
.booking-group-v2 summary,.booking-date-accordion-v155>summary{min-width:0!important}
.booking-summary-copy,.booking-main,.booking-date-copy{min-width:0!important}
